create or replace function public.is_qualifying_return_visit(p_user_id uuid, p_location_id uuid, p_check_in_at timestamptz default now()) returns boolean language plpgsql security definer set search_path='public','auth','extensions','pg_temp' as $function$ declare v_last_check timestamptz; v_today integer; v_cap integer:=5; begin if p_user_id is null or p_location_id is null then return false; end if; select max(checked_in_at) into v_last_check from public.check_ins where user_id=p_user_id and location_id=p_location_id and checked_in_at < p_check_in_at; if v_last_check is not null and p_check_in_at - v_last_check < interval '60 minutes' then return false; end if; select count(*) into v_today from public.progression_metric_events where user_id=p_user_id and metric='check_in' and created_at >= date_trunc('day',p_check_in_at) and created_at < date_trunc('day',p_check_in_at)+interval '1 day'; return v_today < v_cap; end; $function$;
comment on function public.is_qualifying_return_visit(uuid,uuid,timestamptz) is 'Determines whether a check-in can generate progression: repeat experiences remain allowed, but progression requires a return after a 60-minute departure window and is capped at 5 check-in progression events per local UTC day.';

create or replace function public.kleenest_map_check_in(p_location_id uuid, p_lat double precision default null, p_lng double precision default null) returns jsonb language plpgsql security definer set search_path='public','auth','extensions','pg_temp' as $function$ declare uid uuid:=auth.uid(); cid uuid; result jsonb; loc record; distance_m double precision; radius_m double precision; begin if uid is null then raise exception 'AUTH_REQUIRED'; end if; if p_lat is null or p_lng is null or p_lat not between -90 and 90 or p_lng not between -180 and 180 then raise exception 'LOCATION_REQUIRED'; end if; select id,latitude,longitude,coalesce(geofence_radius_m,150)::double precision radius_m into loc from public.locations where id=p_location_id and is_active=true and verification_status='verified'; if not found then raise exception 'LOCATION_NOT_VERIFIED'; end if; if loc.latitude is null or loc.longitude is null then raise exception 'LOCATION_COORDINATES_UNAVAILABLE'; end if; radius_m:=greatest(25,least(coalesce(loc.radius_m,150),5000)); distance_m:=6371000.0*2*asin(sqrt(power(sin(radians(p_lat-loc.latitude)/2),2)+cos(radians(loc.latitude))*cos(radians(p_lat))*power(sin(radians(p_lng-loc.longitude)/2),2))); if distance_m>radius_m then raise exception 'OUTSIDE_GEOFENCE: distance=% radius=%',round(distance_m),round(radius_m); end if; insert into public.check_ins(user_id,location_id,latitude,longitude,distance_meters,verification_method,points_awarded,metadata) values(uid,p_location_id,p_lat,p_lng,distance_m,'gps',10,jsonb_build_object('source','home_geofence','radius_meters',radius_m,'progression_eligible',public.is_qualifying_return_visit(uid,p_location_id))) returning id into cid; return jsonb_build_object('success',true,'check_in_id',cid,'points_awarded',10,'progression_eligible',public.is_qualifying_return_visit(uid,p_location_id),'distance_meters',distance_m,'geofence_radius_meters',radius_m); end; $function$;
